"use client";

import { useRef, useState, useEffect, useCallback, type PointerEvent, type KeyboardEvent } from "react";
import { Check, AlertTriangle } from "lucide-react";
import { cn } from "@/lib/utils";
import { Dialog } from "./dialog";
import { Button } from "./button";

/** A crop rectangle in canvas pixels. */
interface CropBox {
  x: number;
  y: number;
  w: number;
  h: number;
}

export interface ImageCropModalProps {
  open: boolean;
  /** Object URL / URL of the image to crop. The caller owns revoking object URLs. */
  imageSrc: string;
  /**
   * Fixed aspect ratio (width / height) the crop is locked to — e.g. 1 for a
   * square/avatar, 16/9 for a cover. Omit for a free-form crop.
   */
  aspect?: number;
  /** Whether to preview the crop as a circle (avatars). Visual only. */
  circular?: boolean;
  /** Minimum exported width in source pixels; smaller crops are blocked. */
  minWidth?: number;
  /** Output MIME type. Defaults to image/png (lossless). */
  outputType?: string;
  /** Output file name. Defaults to "cropped.png". */
  outputName?: string;
  /** Called with the cropped image as a File when the user confirms. */
  onConfirm: (file: File) => void;
  onCancel: () => void;
}

const CANVAS_MAX_W = 560;
const HANDLE = 14; // px — Fitts's Law: a comfortably large grab target
const MIN_BOX = 48; // px on canvas
const KEY_STEP = 4; // px per arrow press (×5 with Shift)

/**
 * ImageCropModal — an accessible, aspect-aware image cropper. Drag inside the
 * box to reposition, drag the handle (or use the keyboard) to resize; the crop
 * can be locked to an aspect ratio and previewed as a circle. Confirms with the
 * cropped image as a File.
 *
 * Accessibility & UX (grounded in the Mathesis UX books):
 * - Pointer Events unify mouse + touch; the box is keyboard-operable
 *   (arrows move, Shift+arrows resize) so it isn't gesture-only (Fitts's Law,
 *   mobile-patterns).
 * - The resize handle is a large, visible target (Fitts's Law).
 * - Validity + dimensions are announced via an aria-live region with an icon +
 *   text, never color alone (color-perception / accessibility).
 * - Only essential controls are shown (progressive disclosure).
 */
export function ImageCropModal({
  open,
  imageSrc,
  aspect,
  circular,
  minWidth = 0,
  outputType = "image/png",
  outputName = "cropped.png",
  onConfirm,
  onCancel,
}: ImageCropModalProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const imgRef = useRef<HTMLImageElement | null>(null);
  const [crop, setCrop] = useState<CropBox>({ x: 0, y: 0, w: 0, h: 0 });
  const [scale, setScale] = useState(1); // source px per canvas px
  const [canvasSize, setCanvasSize] = useState({ w: 0, h: 0 });
  const drag = useRef<{ mode: "move" | "resize"; px: number; py: number; box: CropBox } | null>(null);

  const outWidth = Math.round(crop.w * scale);
  const outHeight = Math.round(crop.h * scale);
  const tooSmall = minWidth > 0 && outWidth < minWidth;

  // Clamp a box to canvas bounds while (optionally) preserving aspect.
  const clampBox = useCallback(
    (box: CropBox, cw: number, ch: number): CropBox => {
      let { x, y, w, h } = box;
      w = Math.max(MIN_BOX, w);
      h = aspect ? w / aspect : Math.max(MIN_BOX, h);
      if (w > cw) { w = cw; h = aspect ? w / aspect : h; }
      if (h > ch) { h = ch; w = aspect ? h * aspect : w; }
      x = Math.max(0, Math.min(x, cw - w));
      y = Math.max(0, Math.min(y, ch - h));
      return { x, y, w, h };
    },
    [aspect]
  );

  // Load image + set initial centered crop.
  useEffect(() => {
    if (!open || !imageSrc) return;
    const img = new window.Image();
    img.onload = () => {
      imgRef.current = img;
      const cw = Math.min(img.naturalWidth, CANVAS_MAX_W);
      const s = img.naturalWidth / cw;
      const ch = Math.round(img.naturalHeight / s);
      setScale(s);
      setCanvasSize({ w: cw, h: ch });
      // Largest aspect-correct box that fits, centered.
      let w = cw;
      let h = aspect ? w / aspect : Math.round(ch * 0.8);
      if (h > ch) { h = ch; w = aspect ? h * aspect : w; }
      setCrop({ x: Math.round((cw - w) / 2), y: Math.round((ch - h) / 2), w, h });
    };
    img.src = imageSrc;
  }, [open, imageSrc, aspect]);

  // Draw the canvas: image, dim overlay, crop border/mask, grid, handle.
  useEffect(() => {
    const canvas = canvasRef.current;
    const img = imgRef.current;
    if (!canvas || !img || crop.w === 0) return;
    const { w: cw, h: ch } = canvasSize;
    canvas.width = cw;
    canvas.height = ch;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    ctx.clearRect(0, 0, cw, ch);
    ctx.drawImage(img, 0, 0, cw, ch);

    // Dim outside the crop.
    ctx.fillStyle = "rgba(0,0,0,0.55)";
    ctx.fillRect(0, 0, cw, crop.y);
    ctx.fillRect(0, crop.y + crop.h, cw, ch - crop.y - crop.h);
    ctx.fillRect(0, crop.y, crop.x, crop.h);
    ctx.fillRect(crop.x + crop.w, crop.y, cw - crop.x - crop.w, crop.h);

    // Circular mask preview: clear a circle within the box.
    if (circular) {
      ctx.save();
      ctx.beginPath();
      const r = Math.min(crop.w, crop.h) / 2;
      ctx.arc(crop.x + crop.w / 2, crop.y + crop.h / 2, r, 0, Math.PI * 2);
      ctx.strokeStyle = "rgba(255,255,255,0.9)";
      ctx.lineWidth = 2;
      ctx.stroke();
      ctx.restore();
    }

    // Crop border.
    ctx.strokeStyle = "#fff";
    ctx.lineWidth = 2;
    ctx.strokeRect(crop.x + 1, crop.y + 1, crop.w - 2, crop.h - 2);

    // Rule-of-thirds grid.
    ctx.strokeStyle = "rgba(255,255,255,0.35)";
    ctx.lineWidth = 1;
    for (let i = 1; i < 3; i++) {
      ctx.beginPath();
      ctx.moveTo(crop.x + (crop.w / 3) * i, crop.y);
      ctx.lineTo(crop.x + (crop.w / 3) * i, crop.y + crop.h);
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(crop.x, crop.y + (crop.h / 3) * i);
      ctx.lineTo(crop.x + crop.w, crop.y + (crop.h / 3) * i);
      ctx.stroke();
    }

    // Resize handle (bottom-right), large for easy grabbing.
    ctx.fillStyle = "#fff";
    ctx.fillRect(crop.x + crop.w - HANDLE, crop.y + crop.h - HANDLE, HANDLE, HANDLE);
    ctx.strokeStyle = "rgba(0,0,0,0.25)";
    ctx.lineWidth = 1;
    ctx.strokeRect(crop.x + crop.w - HANDLE, crop.y + crop.h - HANDLE, HANDLE, HANDLE);
  }, [crop, canvasSize, circular]);

  const toCanvas = (e: PointerEvent<HTMLCanvasElement>) => {
    const canvas = canvasRef.current!;
    const rect = canvas.getBoundingClientRect();
    return {
      x: ((e.clientX - rect.left) / rect.width) * canvas.width,
      y: ((e.clientY - rect.top) / rect.height) * canvas.height,
    };
  };

  const onPointerDown = (e: PointerEvent<HTMLCanvasElement>) => {
    const p = toCanvas(e);
    const onHandle =
      p.x >= crop.x + crop.w - HANDLE - 4 &&
      p.x <= crop.x + crop.w + 4 &&
      p.y >= crop.y + crop.h - HANDLE - 4 &&
      p.y <= crop.y + crop.h + 4;
    const inside = p.x >= crop.x && p.x <= crop.x + crop.w && p.y >= crop.y && p.y <= crop.y + crop.h;
    if (!onHandle && !inside) return;
    canvasRef.current?.setPointerCapture(e.pointerId);
    drag.current = { mode: onHandle ? "resize" : "move", px: p.x, py: p.y, box: crop };
  };

  const onPointerMove = (e: PointerEvent<HTMLCanvasElement>) => {
    if (!drag.current) return;
    const p = toCanvas(e);
    const { mode, px, py, box } = drag.current;
    const { w: cw, h: ch } = canvasSize;
    if (mode === "resize") {
      const nextW = box.w + (p.x - px);
      setCrop(clampBox({ ...box, w: nextW, h: aspect ? nextW / aspect : box.h + (p.y - py) }, cw, ch));
    } else {
      setCrop(clampBox({ ...box, x: box.x + (p.x - px), y: box.y + (p.y - py) }, cw, ch));
    }
  };

  const endDrag = (e: PointerEvent<HTMLCanvasElement>) => {
    drag.current = null;
    canvasRef.current?.releasePointerCapture?.(e.pointerId);
  };

  const onKeyDown = (e: KeyboardEvent<HTMLCanvasElement>) => {
    const { w: cw, h: ch } = canvasSize;
    const step = e.shiftKey ? KEY_STEP * 5 : KEY_STEP;
    const resize = e.altKey; // Alt+arrows resize, arrows move
    let next: CropBox | null = null;
    if (e.key === "ArrowLeft") next = resize ? { ...crop, w: crop.w - step } : { ...crop, x: crop.x - step };
    else if (e.key === "ArrowRight") next = resize ? { ...crop, w: crop.w + step } : { ...crop, x: crop.x + step };
    else if (e.key === "ArrowUp") next = resize ? { ...crop, w: crop.w - step } : { ...crop, y: crop.y - step };
    else if (e.key === "ArrowDown") next = resize ? { ...crop, w: crop.w + step } : { ...crop, y: crop.y + step };
    if (!next) return;
    e.preventDefault();
    if (resize && aspect) next.h = next.w / aspect;
    setCrop(clampBox(next, cw, ch));
  };

  const confirm = () => {
    const img = imgRef.current;
    if (!img || tooSmall) return;
    const sx = crop.x * scale;
    const sy = crop.y * scale;
    const sw = crop.w * scale;
    const sh = crop.h * scale;
    const out = document.createElement("canvas");
    out.width = Math.round(sw);
    out.height = Math.round(sh);
    const ctx = out.getContext("2d");
    if (!ctx) return;
    ctx.drawImage(img, sx, sy, sw, sh, 0, 0, out.width, out.height);
    out.toBlob(
      (blob) => {
        if (blob) onConfirm(new File([blob], outputName, { type: outputType }));
      },
      outputType,
      0.95
    );
  };

  return (
    <Dialog
      open={open}
      onClose={onCancel}
      size="lg"
      title="Crop image"
      description={
        aspect
          ? "Drag to reposition, drag the handle to resize. The crop keeps a fixed shape."
          : "Drag to reposition, drag the handle to resize."
      }
      footer={
        <>
          <Button variant="secondary" onClick={onCancel}>
            Cancel
          </Button>
          <Button onClick={confirm} disabled={tooSmall}>
            Use image
          </Button>
        </>
      }
    >
      <div className="space-y-3">
        <div className="flex items-center justify-center overflow-auto rounded-lg bg-surface-dark p-2" style={{ maxHeight: 420 }}>
          <canvas
            ref={canvasRef}
            tabIndex={0}
            role="slider"
            aria-label="Crop area — arrow keys move, Alt+arrows resize"
            aria-valuetext={`${outWidth} by ${outHeight} pixels`}
            className="max-w-full touch-none rounded outline-none focus-visible:ring-2 focus-visible:ring-accent"
            style={{ cursor: drag.current?.mode === "resize" ? "nwse-resize" : "grab" }}
            onPointerDown={onPointerDown}
            onPointerMove={onPointerMove}
            onPointerUp={endDrag}
            onPointerCancel={endDrag}
            onKeyDown={onKeyDown}
          />
        </div>

        <p
          aria-live="polite"
          className={cn(
            "flex items-center gap-1.5 text-xs font-medium tabular-nums",
            tooSmall ? "text-error" : "text-text-secondary"
          )}
        >
          {tooSmall ? (
            <>
              <AlertTriangle size={13} aria-hidden />
              Crop is {outWidth}px wide — needs at least {minWidth}px.
            </>
          ) : (
            <>
              <Check size={13} className="text-accent" aria-hidden />
              {outWidth} × {outHeight} px
            </>
          )}
        </p>
      </div>
    </Dialog>
  );
}

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

/**
 * Merge class names with clsx semantics + Tailwind conflict resolution.
 * Prefer this in all components.
 */
export function cn(...inputs: ClassValue[]): string {
  return twMerge(clsx(inputs));
}

/**
 * Concatenate class names, filtering out falsy values.
 * @deprecated Prefer {@link cn} — it also resolves Tailwind class conflicts.
 */
export function cx(...args: (string | false | null | undefined)[]): string {
  return args.filter(Boolean).join(" ");
}

/**
 * Focus ring style helper.
 * @deprecated Focus rings are now handled globally via the
 * `:focus-visible` rule in `globals.css` and the `focus-visible:*`
 * utilities. This remains only for backwards compatibility.
 */
export function ring(color: string = "var(--color-accent)") {
  return { outlineColor: color };
}

"use client";

import { useRef, type ReactNode } from "react";
import { createPortal } from "react-dom";
import { X } from "lucide-react";
import { cn } from "@/lib/utils";
import { useMounted, useFocusTrap } from "@/hooks";

type DialogSize = "sm" | "md" | "lg";

const SIZE: Record<DialogSize, string> = {
  sm: "max-w-sm",
  md: "max-w-md",
  lg: "max-w-lg",
};

interface DialogProps {
  open: boolean;
  onClose: () => void;
  title?: ReactNode;
  description?: ReactNode;

  footer?: ReactNode;
  size?: DialogSize;

  closeOnBackdrop?: boolean;
  children?: ReactNode;
}

export function Dialog({
  open,
  onClose,
  title,
  description,
  footer,
  size = "md",
  closeOnBackdrop = true,
  children,
}: DialogProps) {
  const panelRef = useRef<HTMLDivElement>(null);
  const mounted = useMounted();
  useFocusTrap(panelRef, open, onClose);

  if (!open || !mounted) return null;

  const labelledBy = title ? "dialog-title" : undefined;
  const describedBy = description ? "dialog-desc" : undefined;

  return createPortal(
    <div
      className="fixed inset-0 z-[1000] flex items-center justify-center bg-overlay p-4"
      onClick={closeOnBackdrop ? onClose : undefined}
    >
      <div
        ref={panelRef}
        role="dialog"
        aria-modal="true"
        aria-labelledby={labelledBy}
        aria-describedby={describedBy}
        tabIndex={-1}
        onClick={(e) => e.stopPropagation()}
        className={cn(
          "flex w-full flex-col overflow-hidden rounded-xl bg-surface shadow-overlay outline-none",
          SIZE[size]
        )}
      >
        {(title || description) && (
          <div className="flex items-start justify-between gap-4 px-5 pb-3 pt-5">
            <div className="min-w-0">
              {title && (
                <h2 id="dialog-title" className="text-base font-semibold text-text">
                  {title}
                </h2>
              )}
              {description && (
                <p id="dialog-desc" className="mt-1 text-sm leading-relaxed text-text-secondary">
                  {description}
                </p>
              )}
            </div>
            <button
              type="button"
              onClick={onClose}
              aria-label="Close dialog"
              className="-mr-1 -mt-1 shrink-0 rounded-md p-1 text-text-tertiary hover:bg-bg-hover hover:text-text focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent"
            >
              <X size={18} aria-hidden />
            </button>
          </div>
        )}

        {children && <div className="px-5 py-2 text-sm text-text">{children}</div>}

        {footer && (
          <div className="mt-2 flex items-center justify-end gap-2 border-t border-border bg-bg px-5 py-3">
            {footer}
          </div>
        )}
      </div>
    </div>,
    document.body
  );
}

"use client";

import { useState, useEffect } from "react";

/**
 * Returns true once the component has mounted on the client.
 * Useful for portals and anything that needs `document` to exist.
 */
export function useMounted(): boolean {
  const [mounted, setMounted] = useState(false);
  useEffect(() => setMounted(true), []);
  return mounted;
}

"use client";

import { useEffect, type RefObject } from "react";

const FOCUSABLE =
  'a[href],button:not([disabled]),textarea:not([disabled]),input:not([disabled]),select:not([disabled]),[tabindex]:not([tabindex="-1"])';

/**
 * useFocusTrap — while `active`, traps Tab focus within `ref`, focuses the
 * first focusable element on open, restores focus to the previously focused
 * element on close, and calls `onEscape` when Escape is pressed. Also locks
 * body scroll while active.
 */
export function useFocusTrap(
  ref: RefObject<HTMLElement | null>,
  active: boolean,
  onEscape?: () => void
) {
  useEffect(() => {
    if (!active) return;
    const node = ref.current;
    if (!node) return;

    const previouslyFocused = document.activeElement as HTMLElement | null;

    // Focus the first focusable element (or the container).
    const focusables = () =>
      Array.from(node.querySelectorAll<HTMLElement>(FOCUSABLE)).filter(
        (el) => el.offsetParent !== null
      );
    const first = focusables()[0];
    (first ?? node).focus();

    const onKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Escape") {
        e.preventDefault();
        onEscape?.();
        return;
      }
      if (e.key !== "Tab") return;
      const items = focusables();
      if (items.length === 0) {
        e.preventDefault();
        return;
      }
      const firstEl = items[0];
      const lastEl = items[items.length - 1];
      if (e.shiftKey && document.activeElement === firstEl) {
        e.preventDefault();
        lastEl.focus();
      } else if (!e.shiftKey && document.activeElement === lastEl) {
        e.preventDefault();
        firstEl.focus();
      }
    };

    document.addEventListener("keydown", onKeyDown);

    // Lock body scroll.
    const prevOverflow = document.body.style.overflow;
    document.body.style.overflow = "hidden";

    return () => {
      document.removeEventListener("keydown", onKeyDown);
      document.body.style.overflow = prevOverflow;
      previouslyFocused?.focus?.();
    };
  }, [active, ref, onEscape]);
}

"use client";

import { useState, useRef, type MouseEvent, type ReactNode } from "react";
import { createPortal } from "react-dom";
import { Loader2, type LucideIcon } from "lucide-react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";
import { usePopoverPosition, useMounted } from "@/hooks";

const button = cva(
  [
    "relative inline-flex items-center justify-center gap-2 whitespace-nowrap",
    "rounded-lg font-medium transition-[color,background-color,border-color,transform,box-shadow] duration-150 select-none",
    "active:scale-[0.97]",
    "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-offset-2 focus-visible:ring-accent",
    "disabled:pointer-events-none disabled:opacity-60",
    "aria-disabled:pointer-events-none aria-disabled:opacity-60",
  ],
  {
    variants: {
      variant: {
        primary:
          "bg-accent text-on-accent hover:bg-accent-hover active:bg-accent-active border border-transparent shadow-accent hover:shadow-accent active:shadow-sm",
        secondary:
          "bg-surface text-text border border-border hover:bg-bg-hover hover:border-border-hover active:bg-bg-active shadow-sm hover:shadow-md active:shadow-sm",
        ghost:
          "bg-transparent text-text-secondary hover:bg-bg-hover hover:text-text active:bg-bg-active border border-transparent",
        destructive:
          "bg-error text-on-error hover:bg-error-hover active:bg-error-hover border border-transparent focus-visible:ring-error shadow-sm hover:shadow-md active:shadow-sm",
        link: "bg-transparent text-accent underline-offset-2 hover:underline p-0 h-auto active:scale-100",
      },
      size: {

        sm: "h-8 min-h-8 px-2.5 text-sm",
        md: "h-10 min-h-10 px-4 text-sm",
        lg: "h-11 min-h-11 px-5 text-base",
      },
    },
    defaultVariants: { variant: "primary", size: "md" },
  }
);

type ButtonVariant = NonNullable<VariantProps<typeof button>["variant"]>;
type ButtonSize = NonNullable<VariantProps<typeof button>["size"]>;

interface ButtonProps {
  variant?: ButtonVariant;
  size?: ButtonSize;
  loading?: boolean;
  disabled?: boolean;
  disabledReason?: string;
  icon?: LucideIcon;
  iconRight?: LucideIcon;
  children?: ReactNode;
  onClick?: (e: MouseEvent<HTMLButtonElement>) => void;
  title?: string;
  type?: "button" | "submit" | "reset";
  className?: string;

  ariaLabel?: string;
}

export function Button({
  variant = "primary",
  size = "md",
  loading,
  disabled,
  disabledReason,
  icon: Icon,
  iconRight: IconR,
  children,
  onClick,
  title,
  type = "button",
  className,
  ariaLabel,
}: ButtonProps) {
  const [showTip, setShowTip] = useState(false);
  const isDisabled = Boolean(disabled) && !loading;
  const explainable = isDisabled && Boolean(disabledReason);
  const wrapRef = useRef<HTMLSpanElement>(null);
  const mounted = useMounted();
  const tipPosition = usePopoverPosition(wrapRef, showTip, {
    align: "center",
    gap: 8,
    minWidth: 140,
    preferredHeight: 60,
  });

  const iconSize = size === "lg" ? 18 : size === "sm" ? 15 : 16;

  const handleClick = (e: MouseEvent<HTMLButtonElement>) => {
    if (explainable) {
      e.preventDefault();
      return;
    }
    onClick?.(e);
  };

  return (
    <span
      ref={wrapRef}
      className="relative inline-flex"
      onMouseEnter={() => explainable && setShowTip(true)}
      onMouseLeave={() => setShowTip(false)}
    >
      <button
        type={type}
        disabled={(isDisabled && !explainable) || loading}
        aria-disabled={explainable || undefined}
        aria-busy={loading || undefined}
        aria-label={ariaLabel}
        onFocus={() => explainable && setShowTip(true)}
        onBlur={() => setShowTip(false)}
        onClick={handleClick}
        title={!explainable ? title : undefined}
        className={cn(button({ variant, size }), className)}
      >
        {loading && <Loader2 size={14} className="absolute animate-spin" aria-hidden />}
        <span
          className="inline-flex items-center gap-2"
          style={{ opacity: loading ? 0 : 1 }}
        >
          {Icon && <Icon size={iconSize} strokeWidth={2.2} aria-hidden />}
          {children}
          {IconR && <IconR size={iconSize} strokeWidth={2.2} aria-hidden />}
        </span>
      </button>
      {explainable && showTip && tipPosition && mounted &&
        createPortal(
          <span
            role="tooltip"
            className="pointer-events-none z-50 w-max max-w-72 whitespace-pre-line rounded-md bg-surface-dark px-2.5 py-1.5 text-left text-xs leading-snug text-on-dark shadow-lg"
            style={tipPosition.style}
          >
            {disabledReason}
            <span
              className="absolute left-1/2 size-2 -translate-x-1/2 rotate-45 bg-surface-dark"
              style={tipPosition.placement === "top" ? { bottom: -4 } : { top: -4 }}
            />
          </span>,
          document.body
        )}
    </span>
  );
}

"use client";

import { useState, useEffect, useCallback, type RefObject, type CSSProperties } from "react";

interface PopoverPositionOptions {
  align?: "start" | "center" | "end";
  gap?: number;
  viewportPadding?: number;
  preferredHeight?: number;
  matchWidth?: boolean;
  minWidth?: number;
}

interface PopoverPosition {
  placement: "top" | "bottom";
  style: CSSProperties;
}

/**
 * Compute a fixed-position popover style anchored to a ref element.
 * Opens downward by default; flips upward when there isn't room below
 * AND there's more room above. Clamps horizontally so nothing renders
 * past the viewport edge. Re-measures on scroll/resize while open.
 */
export function usePopoverPosition(
  anchorRef: RefObject<HTMLElement | null>,
  open: boolean,
  options: PopoverPositionOptions = {}
): PopoverPosition | null {
  const {
    align = "start",
    gap = 4,
    viewportPadding = 8,
    preferredHeight = 320,
    matchWidth = false,
    minWidth,
  } = options;

  const [position, setPosition] = useState<PopoverPosition | null>(null);

  const measure = useCallback(() => {
    const anchor = anchorRef.current;
    if (!anchor) return;
    const rect = anchor.getBoundingClientRect();
    const vw = window.innerWidth;
    const vh = window.innerHeight;
    const spaceBelow = vh - rect.bottom - viewportPadding;
    const spaceAbove = rect.top - viewportPadding;
    const placement =
      spaceBelow < Math.min(preferredHeight, 160) && spaceAbove > spaceBelow
        ? "top"
        : "bottom";
    const maxHeight = Math.max(
      120,
      Math.min(preferredHeight, placement === "top" ? spaceAbove : spaceBelow)
    );
    const width = matchWidth ? rect.width : minWidth;
    let left = align === "end" && width ? rect.right - width : rect.left;
    if (align === "center" && width)
      left = rect.left + rect.width / 2 - width / 2;
    left = width
      ? Math.min(Math.max(left, viewportPadding), vw - width - viewportPadding)
      : Math.min(Math.max(left, viewportPadding), vw - viewportPadding);

    setPosition({
      placement,
      style: {
        position: "fixed",
        top: placement === "top" ? undefined : rect.bottom + gap,
        bottom: placement === "top" ? vh - rect.top + gap : undefined,
        left,
        width: matchWidth ? rect.width : undefined,
        minWidth: !matchWidth ? minWidth : undefined,
        maxHeight,
      },
    });
  }, [anchorRef, align, gap, viewportPadding, preferredHeight, matchWidth, minWidth]);

  useEffect(() => {
    if (!open) {
      setPosition(null);
      return;
    }
    measure();
    window.addEventListener("scroll", measure, true);
    window.addEventListener("resize", measure);
    return () => {
      window.removeEventListener("scroll", measure, true);
      window.removeEventListener("resize", measure);
    };
  }, [open, measure]);

  return position;
}
